// Code generated by tenon client. DO NOT EDIT.

// 生成的客户端的运行时：发送请求、解析错误和事件流。浏览器的登录凭据是会话 cookie，由浏览器随同源请求自动带上，
// 运行时不接触它；其他环境（例如脚本）用 headers 传 Authorization: Bearer。
// 它随客户端一起生成，是独立的 TypeScript。

/** 创建客户端的选项。 */
export interface ClientOptions {
  /**
   * 接口的地址前缀，与服务端的 BasePath 相同，例如 /api 或 https://api.example.com/api。
   * 传函数时每次请求读取一次，例如租户在路径中：() => `/api/t/${tenant}`。
   */
  baseURL: string | (() => string)
  /** 每次请求附加的请求头，例如 () => ({ "X-Tenant": tenant })；值为空时不发送。接口自己的请求头优先。 */
  headers?: () => Record<string, string | undefined>
  /**
   * 会话（@go-tenon/client 的 createSession）：受保护的接口返回 401 时调用 expired，登录已经失效。
   * 只对发出时的身份有效：请求发出之后登录、退出或切换了身份（generation 变了），401 原样抛出，
   * 不让新的会话失效；403 auth.confirm_required 也不再确认重试，免得用别人的身份重发。
   */
  session?: SessionLike
  /**
   * 受保护的接口返回 403 auth.confirm_required（rest.Confirmed）时调用：让用户再次输入密码或验证码，
   * 确认成功后返回 true，原请求重试一次。不设置时直接抛出 ApiError。
   */
  onConfirmRequired?: () => Promise<boolean>
  /** 请求的语言（Accept-Language），错误的 detail 按它翻译。默认是浏览器的语言。 */
  language?: () => string | undefined
  /** App 的平台和版本，例如 android/2.3.1，作为 X-App-Version 发送。浏览器中的单页应用省略它。 */
  appVersion?: string
  /** 发送请求的函数，默认是全局的 fetch。 */
  fetch?: typeof fetch
}

/** ClientOptions.session 用到的会话方法。 */
export interface SessionLike {
  generation(): number
  expired(): void
}

/** 事件流的选项。 */
export interface StreamOptions {
  /** 停止接收事件。 */
  signal?: AbortSignal
  /** 接着上次收到的事件继续，作为 Last-Event-ID 发送。 */
  lastEventId?: string
}

/** 字段错误：422 时每个字段一条。 */
export interface FieldError {
  /** 出错的位置，例如 body.title；去掉 body. 就是字段名。 */
  location?: string
  /** 按请求的语言翻译的提示。 */
  message: string
  /** 违反的验证规则，例如 validation.min_length。 */
  code?: string
  value?: unknown
}

/** 非 2xx 的响应。 */
export class ApiError extends Error {
  /** HTTP 状态码。 */
  readonly status: number
  /** 业务错误码，例如 article.slug_taken；只有业务错误带它，见 errors.ts 中的常量。 */
  readonly code?: string
  /** 可以展示给用户的说明，已经按请求的语言翻译。 */
  readonly detail?: string
  /** 422 时每个字段的问题。 */
  readonly fields: FieldError[]
  /** 业务错误的公开参数，例如 auth.method_required 的 methods；没有时是空对象。 */
  readonly params: Record<string, unknown>
  /** 请求编号，用户报告问题时附上它。 */
  readonly requestId?: string
  /** 建议的等待秒数，来自 Retry-After 响应头，出现在 429 和部分 503 中。 */
  readonly retryAfter?: number

  constructor(status: number, body: Record<string, unknown> | undefined, requestId?: string, retryAfter?: number) {
    const detail = typeof body?.detail === "string" ? body.detail : undefined
    super(detail ?? (typeof body?.title === "string" ? body.title : `HTTP ${status}`))
    this.name = "ApiError"
    this.status = status
    this.code = typeof body?.code === "string" ? body.code : undefined
    this.detail = detail
    this.fields = Array.isArray(body?.errors) ? (body.errors as FieldError[]) : []
    this.params = isRecord(body?.params) ? body.params : {}
    this.requestId = requestId
    this.retryAfter = retryAfter
  }
}

function isRecord(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v)
}

/** 报告 err 是否是 ApiError；给出 code 时还要求业务错误码相同。 */
export function isApiError(err: unknown, code?: string): err is ApiError {
  return err instanceof ApiError && (code === undefined || err.code === code)
}

/** 下载的文件。 */
export interface Download {
  blob: Blob
  /** Content-Disposition 中的文件名，没有时为空。 */
  filename: string
}

/** 让浏览器把 blob 保存为 filename。 */
export function saveBlob(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob)
  const a = document.createElement("a")
  a.href = url
  a.download = filename
  a.click()
  setTimeout(() => URL.revokeObjectURL(url), 0)
}

/** 生成的代码描述的一次请求。 */
export interface Request {
  method: string
  path: string
  query?: Record<string, unknown>
  headers?: Record<string, unknown>
  body?: unknown
  form?: Record<string, unknown>
  /** 公开的接口：401 不让会话失效。 */
  public?: boolean
}

const confirmRequired = "auth.confirm_required"

/** Runtime 由生成的 createClient 创建，一个客户端一个。 */
export class Runtime {
  constructor(private readonly options: ClientOptions) {}

  /** 发送请求，返回解码后的 JSON；204 等没有内容的响应返回 undefined。 */
  async request<T>(req: Request): Promise<T> {
    const res = await this.send(req)
    if (res.status === 204 || res.headers.get("Content-Length") === "0") return undefined as T
    const text = await res.text()
    return (text ? JSON.parse(text) : undefined) as T
  }

  /** 发送请求，返回响应体和响应头：names 的键是返回的字段名，值是响应头的名字。 */
  async withHeaders<T>(req: Request, names: Record<string, string>): Promise<{ body: T; headers: Record<string, string | undefined> }> {
    const res = await this.send(req)
    const text = res.status === 204 ? "" : await res.text()
    const headers: Record<string, string | undefined> = {}
    for (const [key, name] of Object.entries(names)) headers[key] = res.headers.get(name) ?? undefined
    return { body: (text ? JSON.parse(text) : undefined) as T, headers }
  }

  /** 发送请求，把响应作为文件返回。 */
  async download(req: Request): Promise<Download> {
    const res = await this.send(req)
    return { blob: await res.blob(), filename: filename(res.headers.get("Content-Disposition")) }
  }

  /**
   * 发送请求，逐个返回事件流中的事件；连接结束、收到 [DONE] 或 signal 取消时结束。
   * events 是已知的事件名，服务端新增的、客户端还不认识的事件被跳过。
   */
  async *stream<E>(req: Request, options: StreamOptions = {}, events?: string[]): AsyncGenerator<E> {
    const headers: Record<string, unknown> = { ...req.headers, Accept: "text/event-stream" }
    if (options.lastEventId) headers["Last-Event-ID"] = options.lastEventId
    const res = await this.send({ ...req, headers }, options.signal)
    if (!res.body) return
    const reader = res.body.pipeThrough(new TextDecoderStream()).getReader()
    let buffer = ""
    let event = { name: "", data: [] as string[], id: "" }
    try {
      for (;;) {
        const { done, value } = await reader.read()
        if (done) return
        buffer += value
        let newline: number
        while ((newline = buffer.search(/\r\n|\r|\n/)) >= 0) {
          const line = buffer.slice(0, newline)
          buffer = buffer.slice(newline + (buffer.startsWith("\r\n", newline) ? 2 : 1))
          if (line === "") {
            if (event.data.length > 0) {
              const data = event.data.join("\n")
              if (data === "[DONE]") return
              const name = event.name || "message"
              if (!events || events.includes(name)) yield { event: name, data: JSON.parse(data), id: event.id || undefined } as E
            }
            event = { name: "", data: [], id: event.id }
            continue
          }
          if (line.startsWith(":")) continue
          const colon = line.indexOf(":")
          const field = colon < 0 ? line : line.slice(0, colon)
          const val = colon < 0 ? "" : line.slice(colon + 1).replace(/^ /, "")
          if (field === "event") event.name = val
          else if (field === "data") event.data.push(val)
          else if (field === "id") event.id = val
        }
      }
    } finally {
      reader.cancel().catch(() => {})
    }
  }

  /**
   * 发送请求：403 auth.confirm_required 时确认一次再重试；非 2xx 抛出 ApiError。
   * 受保护的接口 401 时，身份没有变过就让会话失效。
   */
  private async send(req: Request, signal?: AbortSignal): Promise<Response> {
    const session = this.options.session
    const issued = session?.generation()
    const same = () => session === undefined || session.generation() === issued
    let confirmed = false
    for (;;) {
      const res = await this.fetchOnce(req, signal)
      if (res.ok) return res
      if (res.status === 401 && !req.public && same()) session?.expired()
      const err = await toError(res)
      if (err.code === confirmRequired && this.options.onConfirmRequired && !confirmed && same()) {
        confirmed = true
        if ((await this.options.onConfirmRequired()) && same()) continue
      }
      throw err
    }
  }

  private fetchOnce(req: Request, signal?: AbortSignal): Promise<Response> {
    const headers = new Headers()
    for (const [name, value] of Object.entries({ ...this.options.headers?.(), ...req.headers })) {
      if (value !== undefined && value !== null && value !== "") headers.set(name, String(value))
    }
    const language = this.options.language ? this.options.language() : globalThis.navigator?.language
    if (language && !headers.has("Accept-Language")) headers.set("Accept-Language", language)
    if (this.options.appVersion) headers.set("X-App-Version", this.options.appVersion)
    let body: BodyInit | undefined
    if (req.form) {
      body = formData(req.form)
    } else if (req.body !== undefined) {
      headers.set("Content-Type", "application/json")
      body = JSON.stringify(req.body)
    }
    if (!headers.has("Accept")) headers.set("Accept", "application/json")
    const fetcher = this.options.fetch ?? globalThis.fetch.bind(globalThis)
    const base = typeof this.options.baseURL === "function" ? this.options.baseURL() : this.options.baseURL
    return fetcher(url(base, req.path, req.query), {
      method: req.method,
      headers,
      body,
      credentials: "same-origin",
      signal,
    })
  }
}

function url(base: string, path: string, query?: Record<string, unknown>): string {
  const params = new URLSearchParams()
  for (const [name, value] of Object.entries(query ?? {})) {
    if (value === undefined || value === null || value === "") continue
    for (const v of Array.isArray(value) ? value : [value]) params.append(name, String(v))
  }
  const qs = params.toString()
  return base.replace(/\/+$/, "") + path + (qs ? "?" + qs : "")
}

function formData(fields: Record<string, unknown>): FormData {
  const form = new FormData()
  for (const [name, value] of Object.entries(fields)) {
    for (const v of Array.isArray(value) ? value : [value]) {
      if (v === undefined || v === null) continue
      form.append(name, v instanceof Blob ? v : String(v))
    }
  }
  return form
}

async function toError(res: Response): Promise<ApiError> {
  let body: Record<string, unknown> | undefined
  try {
    body = (await res.json()) as Record<string, unknown>
  } catch {
    body = undefined
  }
  const retryAfter = Number(res.headers.get("Retry-After") ?? "")
  return new ApiError(res.status, body, res.headers.get("X-Request-ID") ?? undefined, retryAfter > 0 ? retryAfter : undefined)
}

function filename(disposition: string | null): string {
  if (!disposition) return ""
  const star = /filename\*\s*=\s*UTF-8''([^;]+)/i.exec(disposition)
  if (star) return decodeURIComponent(star[1].trim())
  const plain = /filename\s*=\s*"?([^";]+)"?/i.exec(disposition)
  return plain ? plain[1].trim() : ""
}
